data "aws_ami" "latest_amazon_linux" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["amazon"]
}

data "archive_file" "flask_app" {
  type        = "zip"
  output_path = "lambda.zip"
  source_dir  = "source/flask/"
}

data "archive_file" "lambda" {
  type        = "zip"
  source_file = "source/s3_to_gluecatalog.py"
  output_path = "s3_to_gluecatalog.zip"
}

resource "aws_key_pair" "this" {
  key_name   = "cg-ec2-key-pair-${var.cgid}"
  public_key = file(var.ssh_public_key)
}

resource "aws_instance" "linux_ec2" {
  ami                         = data.aws_ami.latest_amazon_linux.id
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.ec2.name
  subnet_id                   = aws_subnet.public_1.id
  associate_public_ip_address = true

  vpc_security_group_ids = [
    aws_security_group.ec2.id
  ]

  key_name = aws_key_pair.this.key_name

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 8
    delete_on_termination = true
  }

  provisioner "file" {
    source      = data.archive_file.flask_app.output_path
    destination = "/home/ec2-user/flask_app.zip"
    connection {
      type        = "ssh"
      user        = "ec2-user"
      private_key = file(var.ssh_private_key)
      host        = self.public_ip
    }
  }

  provisioner "file" {
    content = templatefile("${path.module}/source/sql_template.tpl", {
      csv_content           = file("source/order_data.csv"), #data.local_file.csv_file.content,
      aws_access_key_id     = aws_iam_access_key.glue_admin_access_key.id,
      aws_secret_access_key = aws_iam_access_key.glue_admin_access_key.secret
    })

    destination = "/home/ec2-user/insert_data.sql"

    connection {
      type        = "ssh"
      user        = "ec2-user"
      private_key = file(var.ssh_private_key)
      host        = self.public_ip
    }
  }

  user_data = <<-EOF
        #!/bin/bash

        echo 'AWS_ACCESS_KEY_ID=${aws_iam_access_key.glue_web_access_key.id}' >> /etc/profile.d/cloudgoat.sh
        echo 'AWS_SECRET_ACCESS_KEY=${aws_iam_access_key.glue_web_access_key.secret}' >> /etc/profile.d/cloudgoat.sh
        echo 'AWS_RDS=${aws_db_instance.rds.endpoint}' >> /etc/profile.d/cloudgoat.sh
        echo 'AWS_S3_BUCKET=${aws_s3_bucket.web.id}' >> /etc/profile.d/cloudgoat.sh
        echo 'AWS_DEFAULT_REGION=${var.region}' >> /etc/profile.d/cloudgoat.sh

        yum update -y
        yum install -y python3 python3-pip
        amazon-linux-extras install -y postgresql14

        psql postgresql://${aws_db_instance.rds.username}:${aws_db_instance.rds.password}@${aws_db_instance.rds.endpoint}/${aws_db_instance.rds.db_name} -f /home/ec2-user/insert_data.sql

        cd /home/ec2-user
        unzip flask_app.zip -d ./flask_app
        cd flask_app

        pip3 install -r requirements.txt

        mv flask.service /etc/systemd/system/flask-app.service

        systemctl daemon-reload
        systemctl enable flask-app.service
        systemctl start flask-app.service
  EOF

  volume_tags = {
    Name = "CloudGoat ${var.cgid} EC2 Instance Root Device"
  }

  tags = {
    Name = "cg-linux-ec2-${var.cgid}"
  }
}

resource "aws_glue_connection" "this" {
  name        = "test-connections"
  description = "This Glue Connection is used to connect to the RDS database."

  connection_type = "JDBC"

  connection_properties = {
    PASSWORD            = var.rds_username
    USERNAME            = var.rds_password
    JDBC_CONNECTION_URL = "jdbc:postgresql://${aws_db_instance.rds.endpoint}/${var.rds_database_name}"
  }

  physical_connection_requirements {
    availability_zone      = "${var.region}a"
    security_group_id_list = [aws_security_group.glue.id]
    subnet_id              = aws_subnet.public_1.id
  }
}

resource "aws_glue_data_catalog_encryption_settings" "example" {
  data_catalog_encryption_settings {
    connection_password_encryption {
      return_connection_password_encrypted = false
    }

    encryption_at_rest {
      catalog_encryption_mode = "DISABLED"
    }
  }
}


resource "aws_glue_job" "glue_job" {
  name     = "ETL_JOB"
  role_arn = aws_iam_role.glue_ETL_role.arn

  command {
    script_location = "s3://${aws_s3_bucket.data.bucket}/${aws_s3_object.glue_script_file.key}"
    python_version  = "3"
    name            = "glueetl"
  }

  default_arguments = {
    "--job-language" = "python"
    "--job-type"     = "ETL"
  }

  worker_type       = "G.1X"
  number_of_workers = 10
  glue_version      = "4.0"

  connections = [aws_glue_connection.this.name] # 위에서 정의한 Glue 연결 사용

  max_retries = 0

  timeout = 3
}

resource "aws_iam_user" "glue_web" {
  name = "cg-run-app-${var.cgid}"
}

resource "aws_iam_access_key" "glue_web_access_key" {
  user = aws_iam_user.glue_web.name
}

resource "aws_iam_policy" "s3_put_policy" {
  name        = "s3_put_policy"
  description = "Policy for putting objects in S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Put"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutBucketPolicy"
        ]
        Resource = aws_s3_bucket.web.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "s3_put_object" {
  policy_arn = aws_iam_policy.s3_put_policy.arn
  user       = aws_iam_user.glue_web.name
}

resource "aws_iam_user_policy_attachment" "user_rds_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
  user       = aws_iam_user.glue_web.name
}


resource "aws_iam_user" "glue_admin" {
  name = "cg-glue-admin-${var.cgid}"
}

resource "aws_iam_user_policy" "glue_management_policy" {
  name = "glue_management_policy"
  user = aws_iam_user.glue_admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "IAMGlueManagement"
        Effect = "Allow"
        Action = [
          "glue:CreateJob",
          "glue:CreateTrigger",
          "glue:StartJobRun",
          "glue:UpdateJob",
          "iam:PassRole",
          "iam:Get*",
          "iam:List*"
        ]
        Resource = "*"
      },
      {
        Sid      = "ListBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.web.arn
      }
    ]
  })
}

resource "aws_iam_access_key" "glue_admin_access_key" {
  user = aws_iam_user.glue_admin.name
}


resource "aws_iam_role" "glue_ETL_role" {
  name        = "glue_ETL_role"
  description = "Role for Glue ETL jobs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "rds.amazonaws.com",
            "glue.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonRDSFullAccess",
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
    "arn:aws:iam::aws:policy/AWSGlueConsoleFullAccess",
    "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
  ]
}


resource "aws_iam_role" "ssm_parameter_role" {
  name = "ssm_parameter_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
    "arn:aws:iam::aws:policy/AmazonSSMFullAccess"
  ]
}


resource "aws_iam_role" "s3_to_gluecatalog_lambda_role" {
  name        = "s3_to_gluecatalog_lambda_role"
  description = "Role for Lambda function that loads data into Glue Catalog"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
    "arn:aws:iam::aws:policy/AWSGlueConsoleFullAccess",
    "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  ]
}


resource "aws_iam_role" "ec2_role" {
  name        = "cg-${var.scenario-name}-ec2-profile"
  description = "Role for EC2 instance"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  ]
}

resource "aws_iam_instance_profile" "ec2" {
  name = "cg-${var.scenario-name}-${var.cgid}-ecs-agent"
  role = aws_iam_role.ec2_role.name
}

resource "aws_lambda_function" "s3_to_gluecatalog" {
  function_name = "s3_to_gluecatalog"
  description   = "This lambda function is triggered by an S3 event and loads data into Glue Catalog"
  handler       = "s3_to_gluecatalog.lambda_handler"
  role          = aws_iam_role.s3_to_gluecatalog_lambda_role.arn
  runtime       = "python3.12"

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  timeout = 180

  environment {
    variables = {
      BUCKET_Scenario2 = aws_s3_bucket.web.id
      BUCKET_Final     = aws_s3_bucket.data.id
      JDBC_URL         = aws_glue_connection.this.connection_properties.JDBC_CONNECTION_URL
    }
  }
}

resource "aws_s3_bucket_notification" "bucket_notification" {
  bucket = aws_s3_bucket.web.id

  lambda_function {
    lambda_function_arn = aws_lambda_function.s3_to_gluecatalog.arn
    events              = ["s3:ObjectCreated:*"]
  }

  depends_on = [aws_lambda_permission.allow_bucket]
}

resource "aws_lambda_permission" "allow_bucket" {
  statement_id  = "s3-trigger-permission"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.s3_to_gluecatalog.arn
  principal     = "s3.amazonaws.com"
  source_arn    = aws_s3_bucket.web.arn
}

output "website_url" {
  description = "The URL of the website"
  value       = "http://${aws_instance.linux_ec2.public_ip}:5000"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

locals {
  bucket_suffix = replace(var.cgid, "/[^a-z0-9-.]/", "-")
}


resource "aws_s3_bucket" "data" {
  bucket        = "cg-data-${local.bucket_suffix}"
  force_destroy = true
}

resource "aws_s3_bucket_acl" "data_acl" {
  depends_on = [
    aws_s3_bucket_ownership_controls.data_ownership
  ]

  bucket = aws_s3_bucket.data.id
  acl    = "private"
}

resource "aws_s3_bucket_ownership_controls" "data_ownership" {
  bucket = aws_s3_bucket.data.id
  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_object" "glue_script_file" {
  bucket = aws_s3_bucket.data.id
  key    = "ETL_JOB.py"
  source = "source/ETL_JOB.py"
}


resource "aws_s3_bucket" "web" {
  bucket        = "cg-web-${local.bucket_suffix}"
  force_destroy = true
}

resource "aws_s3_object" "primary_web_data" {
  bucket = aws_s3_bucket.web.id
  key    = "order_data2.csv"
  source = "source/order_data.csv"
}

resource "aws_s3_bucket_public_access_block" "access_block" {
  bucket = aws_s3_bucket.web.id

  ignore_public_acls      = true
  block_public_acls       = true
  block_public_policy     = false
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "put_object" {
  depends_on = [
    aws_s3_bucket_public_access_block.access_block
  ]

  bucket = aws_s3_bucket.web.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "s3:PutObject"
        Effect    = "Allow"
        Resource  = "${aws_s3_bucket.web.arn}/*"
        Principal = "*"
      }
    ]
  })
}

resource "aws_security_group" "glue" {
  name        = "cg-rds-glue-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over HTTP"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-rds-glue-${var.cgid}"
  }
}

resource "aws_security_group" "ec2" {
  name        = "cg-ec2-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over HTTP"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  ingress {
    from_port   = 5000
    to_port     = 5000
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-ec2-${var.cgid}"
  }
}

resource "aws_security_group" "rds" {
  name        = "cg-rds-psql-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for PostgreSQL RDS Instance"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = concat([aws_vpc.vpc.cidr_block], var.cg_whitelist)
  }

  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }

  tags = {
    Name = "cg-rds-psql-${var.cgid}"
  }
}

resource "aws_ssm_parameter" "flag" {
  name        = "flag"
  description = "this is secret secret-string"
  type        = "String"
  value       = "flag{Best-of-the-Best-12th-CGV}"
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "stack-name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario."
  default     = "Glue_Privesc"
  type        = string
}

variable "ssh_public_key" {
  description = "SSH Public Key"
  default     = "../cloudgoat.pub"
  type        = string
}

variable "ssh_private_key" {
  description = "SSH Private Key"
  default     = "../cloudgoat"
  type        = string
}

variable "rds_database_name" {
  description = "db_name"
  default     = "bob12cgvdb"
  type        = string
}

variable "rds_username" {
  description = "rds_db_username"
  default     = "postgres"
  type        = string
}

variable "rds_password" {
  description = "rds_db_passwrod"
  default     = "bob12cgv"
  type        = string
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.10.0.0/16"
  enable_dns_hostnames = true
  tags = {
    Name = "CloudGoat ${var.cgid} VPC"
  }
}


resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "CloudGoat ${var.cgid}"
  }
}


resource "aws_subnet" "public_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.10.10.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "CloudGoat ${var.cgid} Public a"
  }
}

resource "aws_subnet" "public_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.10.20.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "CloudGoat ${var.cgid} Public b"
  }
}


resource "aws_subnet" "private_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.10.30.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "CloudGoat ${var.cgid} Private a"
  }
}

resource "aws_subnet" "private_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.10.40.0/24"
  vpc_id            = aws_vpc.vpc.id

  tags = {
    Name = "CloudGoat ${var.cgid} Private 2"
  }
}


resource "aws_route_table" "public_subnet" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }

  tags = {
    Name = "CloudGoat ${var.cgid} Route Table for Public Subnet"
  }
}

resource "aws_route_table" "private_subnet" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "CloudGoat ${var.cgid} Route Table for Private Subnet"
  }
}


resource "aws_route_table_association" "public_subnet" {
  for_each = {
    1 = aws_subnet.public_1.id,
    2 = aws_subnet.public_2.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.public_subnet.id
}

resource "aws_route_table_association" "private_subnet" {
  for_each = {
    1 = aws_subnet.private_1.id,
    2 = aws_subnet.private_2.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.private_subnet.id
}


resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = [
    aws_route_table.public_subnet.id
  ]
}

resource "aws_vpc_endpoint" "glue" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${var.region}.glue"
  vpc_endpoint_type = "Interface"
}
